-- ============================================================================
-- Giving the notification purge its index back
--
-- 20260908120000_harden_queue_tables created `notification_created_at_idx`
-- because the nightly purge (cleanup-user-history-job.ts) deletes in batches of
-- 5.000 ordered by "created_at" — read notifications past 90 days, unread past
-- 180. The very next day, 20260909000904_harden_new_queue_tables dropped it:
-- that file is two lines long and was generated by `prisma migrate dev`, which
-- offers to remove every index the schema does not declare.
--
-- Without it each batch is a sequential scan plus a full sort of everything
-- matching the predicate, inside a 5-minute budget (batch-delete.ts). The job
-- logs "stopped early" and the table never drains — it only grows.
--
-- The index is recreated here AND declared in schema.prisma this time, so the
-- next `migrate dev` sees it as expected state instead of as drift. That is
-- the whole difference between this file and the one it undoes.
--
-- Same reasoning as the other queue-table migrations on CREATE INDEX vs
-- CONCURRENTLY: Prisma wraps each migration in one transaction and Postgres
-- refuses CONCURRENTLY inside a transaction block. On a notification table
-- already holding millions of rows, build it by hand before the deploy and
-- mark this migration applied:
--
--   CREATE INDEX CONCURRENTLY IF NOT EXISTS "notification_created_at_idx"
--     ON "notification" ("created_at");
-- ============================================================================

CREATE INDEX IF NOT EXISTS "notification_created_at_idx"
  ON "notification" ("created_at");
